import re

# The fixed regex pattern for URL highlighting
URL_REGEX = r"(file|https|http|ws|wss)://[-0-9a-zA-Z$_+!`(),.?/;:&=#~@]*"

def test_url_regex_with_at_symbol():
    # Test case: URL containing '@' (e.g., user:pass@host)
    url_with_at = "http://user:pass@example.com/path?query=1"

    match = re.search(URL_REGEX, url_with_at)

    if match:
        print(f"SUCCESS: Found match for URL with '@'. Match: {match.group(0)}")
    else:
        print("FAILURE: Did not find match for URL with '@'.")

def test_url_regex_without_at_symbol():
    # Test case: Standard URL
    url_standard = "https://www.google.com/search"

    match = re.search(URL_REGEX, url_standard)

    if match:
        print(f"SUCCESS: Found match for standard URL. Match: {match.group(0)}")
    else:
        print("FAILURE: Did not find match for standard URL.")

if __name__ == "__main__":
    test_url_regex_with_at_symbol()
    test_url_regex_without_at_symbol()
